void MainScreenViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &btnMode)
    {
        //setSensorListScreen
        //When btnMode clicked change screen to SensorList
        //Go to SensorList with no screen transition
        application().gotoSensorListScreenNoTransition();
    }
    if (&src == &btnSensors)
    {
        //setValuesScreen
        //When btnSensors clicked change screen to ValuesScreen
        //Go to ValuesScreen with no screen transition
        application().gotoValuesScreenScreenNoTransition();
    }
    if (&src == &btnSettings)
    {
        //setSettingsScreen
        //When btnSettings clicked change screen to SettingsScreen
        //Go to SettingsScreen with no screen transition
        application().gotoSettingsScreenScreenNoTransition();
    }
}

void MainScreenViewBase::handleTickEvent()
{
    frameCountUpdateSensorDataInterval++;
    if(frameCountUpdateSensorDataInterval == TICK_UPDATESENSORDATA_INTERVAL)
    {
        //updateSensorData
        //When every N tick call virtual function
        //Call updateSensorData
        updateSensorData();
        frameCountUpdateSensorDataInterval = 0;
    }
}
